<style>
.frame-section{
  position: relative;
}

.frame-section h2{
  font-size: 72px;
  font-weight: 800;
  color: #fff;
    line-height: 80px;
}

.frame-section h2 strong{
  font-weight: 800;
  color: #10C6BF;
}

.frame-section p{
    color: #fff;
    font-size:18px;
    
}

.box-description{
    max-width: 600px;
}

.frame-section .grid-frame{
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  background-color: #10C6BF;
}

.frame-section .grid-frame .frame-box{
  width: 100%;
  height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: end;
  gap: 0;
  position: relative;
    align-items: start;
}

.frame-section .grid-frame .frame-box img{
  position: absolute;
  width: 100%;
  height: 100%;
  top:0;
  left:0px;
  z-index: 0;
  object-fit: cover;
}

.frame-section .grid-frame .frame-box .frame-data{
    margin: 25px 50px;
    position: relative;
}

.frame-section .grid-frame .frame-box h3{
  font-size: 24px;
  line-height: 28px;
  font-weight: 800;
}
.frame-section .grid-frame .frame-box h3 strong{
  font-weight: 800;
  color: #10C6BF;
}

.frame-section .frame-fix{
  text-align: center;
  position: absolute;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column ;
  align-items: center;
  top:0px;
  left:0px;
  justify-content: center;
  z-index: 9;
}

.frame-more-info{
  background-color: #212529;
  display: flex;
  padding: 35px ;
  gap: 20px;
}

.frame-column{
  display: flex;
  gap: 15px;
  align-items: start;
  width: 100%;
}

.frame-column svg{
  width: 46px !important;
  height: auto;
  margin-top: 10px;
}
.frame-column h3{
  font-size: 32px;
  line-height: 42px;
  font-weight: 800;
  color: #fff;
  margin: 0px;
}
.frame-column p{
  font-size: 16px;
  line-height: 20px;
  font-weight: 400;
  color: #10C6BF;
  margin: 0px;
  margin: 0px;
}
.frame-column p strong{
  font-weight: 800;
  color: #fff;

}
.frame-vertical{
  position: relative;
  width: 1px;
  background-color: rgba(255, 255, 255, 0.8);
  min-height: 20px;
}

.frame-footer{
  background-color: #212529;
  border-top: 1px solid rgba(255, 255, 255, 0.8); 
  border-bottom: 1px solid rgba(255, 255, 255, 0.8);
  display: flex;
  justify-content: space-between;
}

.frame-footer .frame-vertical{
    margin:10px 0;
}

.frame-btn{
  display: inline-block;
  padding: 5px 15px;
  background-color: #10C6BF;
  border:1px solid #10C6BF;
  color: #fff;
  font-size: 14px;
  line-height: 18px;
  font-weight: 600;
  border-radius:15px;
}
.frame-btn:hover{
    color: #10C6BF;
  background-color: #fff;
}
.frame-box{
  font-size: 14px;
  line-height: 18px;
  font-weight: 600;
  display: flex;
  gap:  15px;
  padding: 14px;
  color:#fff;
  align-items: center;
}
.highlight{
    background-color: #10C6BF;
    color:#fff;
}


@media (max-width:680px) { 
    .frame-section .frame-fix{
        position: relative;
        background-color: #212529;
        padding: 35px;
    }

    .frame-section .grid-frame{
        grid-template-columns: repeat(1, 1fr);
    }

    .frame-more-info{
        flex-direction: column;
    }
    .frame-vertical{
        width: 100%;
        min-height: 1px !important;
    }

    .frame-footer{
        flex-direction: column;
    }

    .frame-box{
        justify-content: center;
    }

    .frame-section h2{
        font-size: 46px;
        line-height: 56px;
    }
    
}
</style>


